                    $lastBurialDate = \Carbon\Carbon::createFromFormat('d-m-Y', trim($dateStr))->format('Y-m-d');
                } catch (\Exception $e) {
                    // If date parsing fails, set to null
                    $lastBurialDate = null;
                }
            }

            // Map the data to match the database schema
            $mappedData = [
                'grave_id' => $permanentGrave['grave_id'],
                'section' => $permanentGrave['section'],
                'row_no' => $permanentGrave['row_no'],
                'grave_no' => $permanentGrave['grave_no'],
                'status' => $permanentGrave['status'] ?? 'available',
                'oldno' => $permanentGrave['oldno'],
                'last_burial_date' => $lastBurialDate,
                'owner_name' => $permanentGrave['owner'], // Map 'owner' to 'owner_name'
                'contact_no' => $permanentGrave['contact_no'],
                'member_id' => $permanentGrave['member_id'],
                'remarks' => $permanentGrave['remarks'],
                'plot_size' => $permanentGrave['plot_size'],
                'is_active' => $permanentGrave['is_active'] ?? true,
                'created_by' => $permanentGrave['created_by'],
                'updated_by' => $permanentGrave['updated_by'],
                'created_at' => now(),
                'updated_at' => now(),
            ];

            // Use updateOrInsert to avoid duplicate entries
            DB::table('permanent_graves')->updateOrInsert(
                ['grave_id' => $permanentGrave['grave_id']], // Search criteria
                $mappedData
            );
        }
    }
}